  ('close-grip-barbell-bench-press', 'incline-push-up-close-grip', 'full', 'crowding', 'Hands-close push-ups mimic the same narrow pressing angle and hit the same triceps-heavy muscles without needing a bar or bench at all.', 'experience', 'strong', 2),
  ('deadlift', 'reverse-band-sumo-deadlift', 'partial', 'preference', 'Sumo deadlift is a viable barbell hip-hinge alternative for lifters whose limb and torso proportions suit a wider stance better than a conventional pull.', 'mechanistic', 'hedged', 2),
  ('decline-barbell-bench-press', 'cable-chest-press', 'full', 'equipment', 'Multiple studies find machine pressing produces similar pec growth and activation to barbell pressing, and strength transfers both directions between the two.', 'cited_study', 'strong', 2),
  ('decline-barbell-bench-press', 'incline-db-press', 'full', 'injury_pain', 'Presented as a shoulder-friendlier stand-in for heavy barbell bench pressing when it bothers the shoulders, while still hitting the same chest region.', 'mechanistic', 'moderate', 2),
  ('high-cable-curls', 'incline-db-curl', 'full', 'crowding', 'Swapping one exercise to dumbbells lets you superset triceps and biceps without repeatedly re-adjusting a single shared cable stack.', 'experience', 'moderate', 2),
  ('incline-db-curl', 'cable-preacher-curl', 'partial', 'preference', 'Both flex the elbow to load the brachioradialis; an unpublished study found the preacher curl''s more lengthened position produced somewhat greater growth.', 'cited_study', 'hedged', 2),
  ('lat-pulldown', 'assisted-pull-up-machine', 'full', 'equipment', 'Pull-ups let the body move through its own natural arc instead of a machine''s fixed track, so the movement works for any torso or arm length.', 'mechanistic', 'strong', 2),
