  ('smith-machine-stiff-leg-deadlift', 'band-good-morning', 'full', 'equipment', 'Good mornings hinge at the hips without a barbell path that stops at the floor, so they work for proportions a stiff-leg deadlift can''t accommodate.', 'experience', 'moderate', 2),
  ('wide-grip-barbell-bench-press', 'close-grip-barbell-bench-press', 'partial', 'preference', 'A closer or reversed grip pushes the movement toward pure shoulder flexion, which some studies link to greater upper-pec activity.', 'cited_study', 'hedged', 2),
  ('45-degree-back-extension', 'barbell-hip-thrust', 'partial', 'equipment', 'Both are hip-extension exercises usable as low-fatigue glute accessory volume; the swap only holds if your goal is glutes, not spinal erectors.', 'mechanistic', 'strong', 1),
  ('45-degree-back-extension', 'band-good-morning', 'full', 'equipment', 'When the actual goal is training the spinal erectors, a loaded hip-hinge like a good morning reproduces that same lower-back extension demand.', 'mechanistic', 'moderate', 1),
  ('assisted-dip-machine', 'deficit-push-up', 'full', 'equipment', 'Deficit push-ups let the chest drop below hand level, recreating the deep pec stretch dips provide, without needing dip handles.', 'mechanistic', 'moderate', 1),
