  ('back-squat', 'trap-bar-deadlift', 'partial', 'skill', 'For a beginner where injury avoidance is the main goal, a hex bar deadlift is quicker to learn correctly and harder to perform with bad form than a squat.', 'experience', 'moderate', 1),
  ('back-squat', 'db-squat', 'partial', 'equipment', 'Home dumbbells can''t match barbell loading, but the lighter load is easier to recover from, so frequency can rise to three or four times weekly.', 'experience', 'moderate', 1),
  ('band-skull-crusher', 'incline-push-up-close-grip', 'partial', 'equipment', 'A close-grip push-up bends the elbows through a similar path to a skull crusher, so it can hammer the triceps without any weights.', 'mechanistic', 'moderate', 1),
  ('band-skull-crusher', 'bench-press', 'inferior', 'time', 'A controlled study found bench press alone still grows the triceps as a secondary mover, but only about half as much as direct skull-crusher work.', 'cited_study', 'strong', 1),
