  ('barbell-deadlift', 'barbell-bulgarian-split-squat', 'partial', 'preference', 'Both can serve as the day''s heavy compound lift; leaning the torso forward on the split squat pulls extra glute and hamstring work into an otherwise quad-focused move.', 'mechanistic', 'strong', 1),
  ('barbell-deadlift', 'back-squat', 'partial', 'preference', 'Heavy squat volume builds much of the same posterior-chain and total-body strength that carries over to the deadlift, easing the need for direct deadlift work.', 'experience', 'hedged', 1),
  ('barbell-deadlift', 'barbell-glute-bridge', 'inferior', 'injury_pain', 'A single-leg glute bridge keeps training the hip-hinge and glute pattern of a deadlift without a standing pull through the hurt leg.', 'experience', 'moderate', 1),
  ('barbell-deadlift', 'snatch-deadlift', 'partial', 'injury_pain', 'Snatch-grip pulls the same hip-hinge deadlift pattern but with reduced load, letting a lifter repeat deadlifting later in the week without adding as much cumulative strain.', 'mechanistic', 'moderate', 1),
