  ('barbell-seated-calf-raise', 'seated-calf-raise', 'inferior', 'equipment', 'Their research found sitting down for calf raises grew the calf less overall than doing them standing with straight legs, probably from less gastrocnemius stretch under load.', 'cited_study', 'strong', 1),
  ('barbell-seated-calf-raise', 'seated-calf-stretch', 'full', 'equipment', 'One cited trial found an hour of daily loaded calf stretching produced hypertrophy similar to a standard calf-raise program, suggesting passive tension alone can drive growth.', 'cited_study', 'hedged', 1),
  ('barbell-shoulder-press', 'arnold-dumbbell-press', 'partial', 'equipment', 'A standing dumbbell Arnold press still loads the shoulders hard through a similar pressing arc when no machine is available, using lighter weights.', 'experience', 'moderate', 1),
  ('barbell-shoulder-press', 'barbell-front-raise', 'partial', 'injury_pain', 'A front raise isolates the front delt through shoulder flexion alone, avoiding the elbow-extension work a pressing movement would place on fatigued triceps.', 'mechanistic', 'moderate', 1),
  ('barbell-shoulder-press', 'db-shoulder-press', 'full', 'preference', 'Presenter''s stated preference: dumbbell pressing hits the front delts like a barbell press does but puts less strain on the shoulder joints.', 'mechanistic', 'moderate', 1),
  ('barbell-side-split-squat', 'barbell-bulgarian-split-squat', 'partial', 'equipment', 'Elevating the rear foot shifts more bodyweight onto the front leg (about 85% vs 75%), giving a harder quad stimulus when only light dumbbells are available.', 'cited_study', 'strong', 1),
