  ('bench-press-with-chains', 'assisted-dip-machine', 'partial', 'preference', 'Same logic as pec flies: dips hit the pecs and triceps well without adding to the heavy systemic fatigue equipped pressing already causes.', 'mechanistic', 'moderate', 1),
  ('bodyweight-squat', 'single-leg-high-box-squat', 'partial', 'equipment', 'Once regular bodyweight squats stop being challenging and no weight can be added, dropping to one leg increases the per-leg demand and difficulty.', 'mechanistic', 'moderate', 1),
  ('cable-chest-press', 'decline-barbell-bench-press', 'partial', 'crowding', 'When his usual chest-press machine was occupied, he switched to bench press and still pushed his pecs hard with heavy sets and drop sets.', 'experience', 'moderate', 1),
  ('cable-chest-press', 'incline-db-press', 'full', 'preference', 'When a machine press stops producing results or bothers the joints, switching back to dumbbell pressing at the same angle was described as personally more reliable.', 'experience', 'hedged', 1),
